"use client";

import { useState } from "react";
import Link from "next/link";
import Footer from "@/components/Footer";

export default function Warranty() {
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    orderNumber: "",
    purchaseDate: "",
  });
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In production, this would send to a backend
    const message = `مرحبا، أرغب في تفعيل الضمان الذهبي\nالاسم: ${formData.name}\nرقم الهاتف: ${formData.phone}\nرقم الطلب: ${formData.orderNumber}\nتاريخ الشراء: ${formData.purchaseDate}`;
    window.open(`https://wa.me/96872022112?text=${encodeURIComponent(message)}`, "_blank");
    setSubmitted(true);
  };

  return (
    <div className="min-h-screen" style={{ backgroundColor: "var(--color-accent)" }}>
      <div style={{ backgroundColor: "var(--color-primary)" }} className="py-20 sm:py-28 text-center">
        <h1 className="text-4xl sm:text-5xl font-bold text-white mb-4">تفعيل الضمان الذهبي</h1>
        <p className="text-white/70 text-lg">فعّل ضمانك واستمتع براحة البال</p>
      </div>

      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <div className="bg-white rounded-2xl p-8 sm:p-12 shadow-sm">
          {/* Warranty Info */}
          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 rounded-full mb-4" style={{ backgroundColor: "var(--color-gold)", color: "var(--color-primary-dark)" }}>
              <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"/>
              </svg>
            </div>
            <h2 className="text-2xl font-bold mb-2" style={{ color: "var(--color-primary)" }}>ضمان 30 يوم</h2>
            <p className="text-gray-600">فعّل ضمانك الذهبي خلال 7 أيام من استلام المنتج</p>
          </div>

          {!submitted ? (
            <form onSubmit={handleSubmit} className="space-y-6 max-w-lg mx-auto">
              <div>
                <label className="block text-sm font-semibold mb-2" style={{ color: "var(--color-primary)" }}>الاسم الكامل</label>
                <input
                  type="text"
                  required
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30 text-right"
                  style={{ direction: "rtl" }}
                  placeholder="أدخل اسمك الكامل"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold mb-2" style={{ color: "var(--color-primary)" }}>رقم الهاتف</label>
                <input
                  type="tel"
                  required
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30 text-right"
                  style={{ direction: "rtl" }}
                  placeholder="+968 XXXX XXXX"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold mb-2" style={{ color: "var(--color-primary)" }}>رقم الطلب</label>
                <input
                  type="text"
                  required
                  value={formData.orderNumber}
                  onChange={(e) => setFormData({ ...formData, orderNumber: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30 text-right"
                  style={{ direction: "rtl" }}
                  placeholder="رقم الطلب الخاص بك"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold mb-2" style={{ color: "var(--color-primary)" }}>تاريخ الشراء</label>
                <input
                  type="date"
                  required
                  value={formData.purchaseDate}
                  onChange={(e) => setFormData({ ...formData, purchaseDate: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30"
                />
              </div>

              <button
                type="submit"
                className="w-full py-4 rounded-full text-white font-bold text-lg transition-all duration-300 hover:scale-105"
                style={{ backgroundColor: "var(--color-primary)" }}
              >
                تفعيل الضمان
              </button>
            </form>
          ) : (
            <div className="text-center py-10">
              <div className="text-6xl mb-4" style={{ color: "var(--color-whatsapp)" }}>✓</div>
              <h3 className="text-2xl font-bold mb-2" style={{ color: "var(--color-primary)" }}>تم إرسال طلب التفعيل!</h3>
              <p className="text-gray-600">سيتم التواصل معك عبر واتساب لتأكيد تفعيل الضمان</p>
            </div>
          )}
        </div>

        <div className="text-center mt-8">
          <Link href="/" className="inline-flex items-center gap-2 font-semibold transition-colors" style={{ color: "var(--color-primary)" }}>
            <svg className="w-5 h-5 rotate-180" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            العودة للرئيسية
          </Link>
        </div>
      </div>
      <Footer />
    </div>
  );
}
